faqs=[
('Is Bharathidasan University a public university?','Bharathidasan University is a Tamil Nadu state university established in 1982. The UGC consolidated register lists it at Palkalaiperur, Tiruchirappalli; its university departments are separate from the colleges affiliated to it.'),
('Which campus will I study at?','The university operates its main Palkalaiperur campus and the Khajamalai city campus. Palkalaiperur contains the central library, sports complex, health centre and administrative buildings; department and hostel allocation determine your daily campus.'),
('Are the programmes taught in English?','The Financial Management MBA regulations specify English. The integrated M.Tech programmes have English and Tamil options; the offerings shown here cover English medium only. Confirm the English class allocation with the department when accepting an integrated-programme place.'),
('Can I enter an integrated M.Tech after school?','The six-year integrated programmes admit after Plus Two or equivalent, with subjects specified separately for Biotechnology, Computer Science and Engineering, and Geological Technology and Geoinformatics. The university describes entrance-based selection for integrated programmes; this is a longer route than a two-year postgraduate M.Tech after a prior degree.'),
('What does the Financial Management MBA require?','For 2026-27, eligible qualifications include B.Com., B.B.A., Corporate Secretaryship, Bank Management and related Commerce degrees, with an Accountancy course and at least 50% under Part III. Selection gives equal weight to Part III marks and the entrance test. Valid scores in the tests named in the prospectus allow entrance-test exemption.'),
('How much is tuition for Indian students?','The 2026-27 tuition for the Financial Management MBA and the integrated M.Tech options shown here is INR 20,000 per semester. Two semesters therefore carry INR 40,000 tuition, with laboratory and university charges where applicable. Admission totals vary by programme and prior board or university; accommodation is additional.'),
('Do foreign students pay the same amount?','Foreign-student tuition follows a separate USD policy, with different treatment for developed and other countries. Its outside-India qualification column also includes recognition charges. Obtain an individual international fee assessment rather than treating an Indian-student admission total as your foreign-national tuition.'),
('How do I apply to a university department?','Use the regular University Departments admissions portal and select the exact programme. The general MBA, Logistics and Supply Chain Management MBA, and International Business MBA use Tamil Nadu MBA/MCA counselling instead; Financial Management has its own department selection rules. Students Traffic can help identify the route for your qualification.'),
('When does the academic year begin?','Applications usually open around May and June, followed by classes in July. That is a usual annual pattern. The next admission cycle needs its own notification before an application deadline or reporting date can be relied on.'),
('Can international and NRI students apply?','The International Students Cell covers foreign passport holders, NRIs educated abroad and qualifying NRI-sponsored students. It describes postgraduate and integrated programmes and assesses overseas qualifications. Category-specific admission, fees and document requirements need confirmation for the intended programme.'),
('Is hostel accommodation available?','Hostels operate across Palkalaiperur and Khajamalai, with separate accommodation for men and women and dedicated research-scholar hostels. Hostel eligibility is limited to students living at least 40 kilometres away. Rooms have Wi-Fi, dining facilities and reading or recreation spaces; a current accommodation quotation is needed.'),
('Does the MBA include practical training?','The Financial Management MBA requires at least four weeks of institutional training after semester two and a final-semester project. The regulations describe work in finance firms and a Centre for Financial Markets associated with NSE Academy Limited. These are curriculum features and do not promise employment or a particular salary.')]
u=dict(countrySlug='india',slug=S,name='Bharathidasan University',city='Tiruchirappalli',type='Public',establishedYear=1982,officialWebsite='https://www.bdu.ac.in/',mediaAttribution={},summary='Bharathidasan University is a public state university established in 1982 in Tiruchirappalli, Tamil Nadu. Its Palkalaiperur and Khajamalai campuses teach postgraduate and integrated degrees across science, engineering, management, social sciences, humanities and education, alongside vocational and specialist study.',campusLifestyle='Palkalaiperur houses the central library, sports complex, bank, post office, canteen and health centre. Khajamalai hosts selected departments and entrepreneurship activities. Library services include INFLIBNET, DELNET, electronic resources and a 24-hour Garden Library; sports facilities include an indoor stadium, gymnasium, yoga centre and 400-metre athletics track.',cityProfile='Bharathidasan University is based in Tiruchirappalli, Tamil Nadu. Its Palkalaiperur main campus is on the Tiruchirappalli–Pudukkottai–Rameswaram highway; a second campus is at Khajamalai in the city. Department and accommodation allocation matter when planning the daily journey between university facilities.',practicalExposure='The Financial Management MBA includes at least four weeks of institutional training after semester two and a final-semester project. Its Centre for Financial Markets works in association with NSE Academy Limited, with finance-firm case analysis and project reports built into the curriculum. Integrated M.Tech students share a first-year curriculum before their academic work is administered by the relevant specialist department. The university also operates a Placement and Training Cell that organises job fairs.',hostelOverview='Hostels are located at Palkalaiperur and Khajamalai, including separate accommodation for men, women and research scholars. Eligibility is limited to students residing at least 40 kilometres from the university. Facilities include Wi-Fi, kitchens and dining rooms, water supply, reading rooms and recreation areas. Current room and mess charges need a hostel quotation before budgeting.',dietarySupport='University hostels have kitchens and dining facilities, and the Palkalaiperur campus has a canteen. Discuss required meals and any dietary restrictions with the hostel before taking a place; current mess charges need a separate accommodation quotation.',safetyOverview='An Anti-Ragging Cell addresses ragging, while the anti-sexual-harassment committee and Students Affairs Cell handle related complaints and grievances. The main campus includes a health centre. These are named campus services, rather than a guarantee about personal safety.',studentSupport='The International Students Cell handles overseas admission categories and qualification assessment. The Centre for Differently Abled Persons supports disability-specific study routes, and the university runs student-affairs and grievance services. Students Traffic can help match qualifications, programme requirements and the appropriate application route.',whyChoose=['A state university with university-department study across Palkalaiperur and Khajamalai campuses.','English-medium Financial Management MBA with institutional training and a final-semester project.','Integrated M.Tech options admit after Plus Two, with subject-specific eligibility and an English-medium route.'],thingsToConsider=['Integrated M.Tech programmes take six years from Plus Two; they are different entry routes from postgraduate M.Tech degrees.','The hostel eligibility rule requires residence at least 40 kilometres from the university.','Foreign-national tuition follows a separate USD policy; Indian admission totals do not represent an international tuition quote.','The usual July intake does not establish next-cycle application or reporting dates.'],bestFitFor=['Commerce graduates seeking the Financial Management MBA with an accountancy background.','School graduates meeting the specific science-subject requirements for an integrated M.Tech.','Applicants who want university-department study and can plan around department and campus allocation.'],industryPartners=['NSE Academy Limited — association with the Centre for Financial Markets'],recognitionBadges=['UGC — State University listed in the consolidated universities register','UGC — included under Section 12(B), as listed in the state universities register'],recognitionLinks=[dict(label='UGC consolidated universities register, entry 792',url=U),dict(label='UGC Section 12(B) state universities register, entry 144',url=B)],faq=[dict(question=q,answer=a) for q,a in faqs],researchSources=[dict(label=label,url=url,kind=kind,checkedAt=D) for label,url,kind in [('2026-27 regular admissions prospectus',P,'official-fee'),('International Students Cell',I,'official-university'),('MBA Financial Management regulations',M,'official-program'),('Centre for Engineering and Technology',E,'official-program'),('UGC universities register',U,'recognition'),('UGC Section 12(B) register',B,'recognition')]],admissionsContent=dict(contentState='research_ready',scope='University departments and centres at Palkalaiperur and Khajamalai; affiliated colleges, distance/online education and Ph.D. excluded. Only verified English-medium programmes are packaged; other regular programmes remain in the full inventory with exact holds.',sectionStates=dict(decisionSummary='published',eligibility='published',fees='published',admissions='published',academics='published',recognition='published',studentLiving='published',scholarships='absent',funding='absent',placements='research_ready'),ctas=[dict(trigger='eligibility',label='Check my Bharathidasan University eligibility',capture=['intended programme','qualifying subjects and marks','nationality and prior board or university']),dict(trigger='fees',label='Plan my Bharathidasan University budget',capture=['programme','fee category','hostel needs']),dict(trigger='application',label='Plan my Bharathidasan application',capture=['programme','admission cycle','document readiness'])]),programmes=programmes)
ev('identity','Established February 1982. Palkalaiperur main campus and Khajamalai city campus; university departments teach across sciences, management, humanities, engineering and education.')
